#include "uart_workbench.h"
#include "uart_tool_form.h"
#include "uart_files.h"
#include <cmath>

bool UartWorkbench::start_transfer(size_t i,ProtocolTransferJob::Options options,std::wstring& error){if(!acquire(i,ToolRun::Transfer,error))return false;auto& run=runs_[i];auto* queue=i==0?primary_queue_:&secondary_.queue();if(!queue){run.kind=ToolRun::None;error=L"Serial operation queue is unavailable.";return false;}const auto generation=run.generation;const auto target=i==0?primary_status_.settings.port.device:secondary_.settings().port.device;
    const bool started=transfers_[i].start(std::move(options),i==0?*primary_:secondary_.traffic,generation,
        [queue,generation,target](std::string bytes,uint64_t& id,std::wstring& error,std::function<void(const SerialOperationResult&)> completion){SerialOperation operation;operation.bytes=std::move(bytes);operation.target=target;operation.required_generation=generation;operation.pacing_override=true;operation.completion=std::move(completion);return queue->submit(std::move(operation),id,error);},
        [queue,generation]{return queue->current(generation);},[queue](uint64_t id){queue->cancel_pending(id);});
    if(!started){run.kind=ToolRun::None;error=L"Cannot start transfer worker.";return false;}if(i==0){Request r;r.action=Request::DiscardText;request(r);}run.status=L"Transfer: preparing files / waiting for peer handshake...";return true;
}
void UartWorkbench::transfer_dialog(size_t i){const auto generation=i==0?primary_status_.generation:secondary_.generation();UartToolForm form(i?L"File transfer - Port B":L"File transfer - Port A",L"PC-side X/YMODEM, no flashing logic. Apply opens the file/folder picker and starts the selected protocol. YMODEM supports batches (1..128) and never overwrites received names. XMODEM has no filename/length: blank receive length keeps all padding. Progress is in the port status; Tools > Stop cancels. No reconnect resume.",
    {{L"Direction",L"Send",{L"Send",L"Receive"}},{L"Protocol",L"XMODEM CRC",{L"XMODEM checksum",L"XMODEM CRC",L"XMODEM 1K",L"YMODEM batch"}},{L"X receive bytes (optional)",L""},{L"Timeout (ms)",L"3000"},{L"Attempts per block",L"10"}},{},[](const auto& f,std::wstring& error){double timeout=0,retries=0,size=0;if(!uart_number(f[3],100,60000,timeout)||timeout!=std::floor(timeout)||!uart_number(f[4],1,10,retries)||retries!=std::floor(retries)||(!f[2].empty()&&(!uart_number(f[2],0,64.0*1024*1024*1024,size)||size!=std::floor(size)))){error=L"Timeout 100..60000 ms, attempts 1..10, optional whole-byte length 0..64 GiB.";return false;}return true;},this);
    if(form.DoModal()!=IDOK||shutdown_)return;const auto f=form.values();ProtocolTransferJob::Options options;options.receive=f[0]==L"Receive";const std::vector<std::wstring> modes={L"XMODEM checksum",L"XMODEM CRC",L"XMODEM 1K",L"YMODEM batch"};options.protocol.mode=static_cast<BlockMode>(std::find(modes.begin(),modes.end(),f[1])-modes.begin());double timeout=0,retries=0,size=0;uart_number(f[3],100,60000,timeout);uart_number(f[4],1,10,retries);options.protocol.timeout_ms=static_cast<unsigned>(timeout);options.protocol.retries=static_cast<unsigned>(retries);if(!f[2].empty()){uart_number(f[2],0,64.0*1024*1024*1024,size);options.x_size=static_cast<uint64_t>(size);}
    const bool batch=options.protocol.mode==BlockMode::Ymodem;if(options.receive&&batch){CFolderPickerDialog picker(nullptr,OFN_PATHMUSTEXIST,this);if(picker.DoModal()!=IDOK)return;options.paths.emplace_back(picker.GetPathName().GetString());}
    else {std::vector<wchar_t> names(65536);CFileDialog picker(!options.receive,L"bin",nullptr,OFN_HIDEREADONLY|(options.receive?OFN_OVERWRITEPROMPT:OFN_FILEMUSTEXIST)|(batch&&!options.receive?OFN_ALLOWMULTISELECT:0),L"All files (*.*)|*.*||",this);picker.GetOFN().lpstrFile=names.data();picker.GetOFN().nMaxFile=static_cast<DWORD>(names.size());if(picker.DoModal()!=IDOK)return;auto position=picker.GetStartPosition();while(position)options.paths.emplace_back(picker.GetNextPathName(position).GetString());options.replace=options.receive;}
    if(shutdown_||generation!=(i==0?primary_status_.generation:secondary_.generation())){warn(L"Connection changed while choosing transfer options/files; review and start again.");return;}std::wstring error;if(!start_transfer(i,std::move(options),error))warn(error);
}
